import React, { useContext, useState } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { FiPlus, FiBriefcase, FiUsers } from 'react-icons/fi';
import CreateProject from '../projects/CreateProject';

const ClientDashboard = () => {
  const { user } = useContext(AuthContext);
  const [showCreateProject, setShowCreateProject] = useState(false);

  if (showCreateProject) {
    return <CreateProject />;
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-800">
            Welcome, {user?.name}! 👋
          </h1>
          <p className="text-gray-600 mt-2">
            Manage your projects and find talented students
          </p>
        </div>

        {/* Stats */}
        <div className="grid md:grid-cols-3 gap-6 mb-8">

          <div className="bg-white rounded-lg shadow-md p-6">
            <FiBriefcase className="text-4xl text-primary mb-4" />
            <p className="text-gray-600 text-sm">Active Projects</p>
            <p className="text-3xl font-bold text-gray-800 mt-1">5</p>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <FiUsers className="text-4xl text-green-500 mb-4" />
            <p className="text-gray-600 text-sm">Applications</p>
            <p className="text-3xl font-bold text-gray-800 mt-1">23</p>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <button
              onClick={() => setShowCreateProject(true)}
              className="w-full flex items-center justify-center space-x-2 px-6 py-4 bg-primary text-white rounded-lg hover:bg-secondary transition font-semibold"
            >
              <FiPlus />
              <span>Post New Project</span>
            </button>
          </div>

        </div>

        {/* Recent Projects */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">
            Your Projects
          </h2>

          <div className="text-center text-gray-600 py-8">
            <p>No projects yet. Click "Post New Project" to get started!</p>
          </div>
        </div>

      </div>
    </div>
  );
};

export default ClientDashboard;
